function fig = bb_pll_setup_gui(state_file)
% Generated by GitHub Copilot under Lance Lascari's direction.
% Persistent PLL setup editor and readable aa_run script generator.
% Local _pll_setup_last.mat is git-ignored; no analysis runs until requested.
tool_directory=fileparts(mfilename('fullpath'));
% Called as a command, wait for the window to close, then run any requested
% script outside the button callback (long callbacks can freeze the Qt GUI).
wait_for_close=nargout==0;
pending_script='';
if nargin==0
    state_file=fullfile(tool_directory,'_pll_setup_last.mat');
end
state_directory=fileparts(state_file);
if isempty(state_directory)
    state_directory=pwd;
    state_file=fullfile(state_directory,state_file);
end
if exist(state_directory,'dir')~=7
    error('Local setup-state directory does not exist');
end
[defaults,groups]=rfdude_pll_configuration();
raw_defaults=raw_configuration(defaults);
raw_defaults.o_sweep_type='List';
raw_defaults.o_sweep_start='1000';
raw_defaults.o_sweep_stop='4000';
raw_defaults.o_sweep_step='1000';
raw_defaults.o_sweep_points_per_octave='1';
last=struct('raw',raw_defaults,'section',1,'run_script',false, ...
    'script_name','aa_run_user_config_XXXX_design.m');
if exist(state_file,'file')==2
    try
        stored=load(state_file,'last');
        if ~isfield(stored,'last') || ~isstruct(stored.last) || ...
                ~all(isfield(stored.last,{'raw','section','run_script','script_name'}))
            error('Saved configurator state is incomplete');
        end
        names=fieldnames(raw_defaults);
        for k=1:numel(names)
            if isfield(stored.last.raw,names{k})
                value=stored.last.raw.(names{k});
                if ~ischar(value) || ~isrow(value) && ~isempty(value)
                    error('Saved field %s is not text',names{k});
                end
                last.raw.(names{k})=value;
            end
        end
        validateattributes(stored.last.section,{'numeric'},{'scalar','integer','>=',1,'<=',size(groups,1)+1});
        validateattributes(stored.last.run_script,{'numeric','logical'},{'scalar','binary'});
        if ~ischar(stored.last.script_name) || ~isrow(stored.last.script_name)
            error('Saved script name is invalid');
        end
        last.section=stored.last.section;
        last.run_script=stored.last.run_script;
        last.script_name=stored.last.script_name;
    catch err
        warning('Could not restore PLL configurator state: %s',err.message);
        errordlg(err.message,'Could not restore last PLL setup');
    end
end
option_names=fieldnames(defaults.run_options_s);
option_names(strcmp(option_names,'bEnableDataViewer'))=[];
index=find(strcmp(option_names,'sweep_values'));
option_names=[option_names(1:index-1); {'sweep_type'}; option_names(index); ...
    {'sweep_start';'sweep_stop';'sweep_step';'sweep_points_per_octave'}; option_names(index+1:end)];
groups(end+1,:)={'Run / sweep',option_names.'};
fig=figure('name','PLL run configurator','numbertitle','off', ...
    'menubar','none','toolbar','none','position',[100 100 950 750], ...
    'closerequestfcn',@close_gui,'tag','pll_setup_gui');
controls=struct();
labels=struct();
panels=cell(1,size(groups,1));
section_control=uicontrol(fig,'style','listbox','units','normalized', ...
    'position',[.02 .29 .22 .64],'string',groups(:,1),'value',last.section, ...
    'callback',@change_section,'tag','pll_setup_section');
for g=1:size(groups,1)
    panels{g}=uipanel(fig,'title',groups{g,1},'units','normalized', ...
        'position',[.26 .29 .72 .64],'visible','off');
    names=groups{g,2};
    row=0;
    for k=1:numel(names)
        name=names{k};
        y=.90-(k-1)*.085;
        if g==7
            % Alternative sweep inputs share rows; only the selected mode is visible.
            if any(strcmp(name,{'sweep_start','sweep_points_per_octave'}))
                row=row-1;
            end
            y=.90-row*.078;
            row=row+1;
        end
        key=field_key(g,name);
        labels.(key)=uicontrol(panels{g},'style','text','units','normalized', ...
            'position',[.02 y .43 .055],'horizontalalignment','left','string',field_label(name));
        if any(strcmp(name,{'sweep_parameter','sweep_type'}))
            if strcmp(name,'sweep_type')
                choices={'List','Start / stop / step','Log (points per octave)'};
            else
                choices={'BW_desired_Hz','PM_desired_deg','Fref_Hz','Kphi_A_cycle','fout_desired_Hz'};
            end
            selected=find(strcmp(choices,last.raw.(key)),1);
            if isempty(selected)
                selected=1;
                last.raw.(key)=choices{1};
            end
            controls.(key)=uicontrol(panels{g},'style','popupmenu','string',choices, ...
                'value',selected,'units','normalized','position',[.46 y .50 .06], ...
                'callback',@edited,'tag',key);
        elseif is_boolean(name)
            controls.(key)=uicontrol(panels{g},'style','checkbox','units','normalized', ...
                'position',[.46 y .50 .06],'value',strcmp(last.raw.(key),'1'), ...
                'callback',@edited,'tag',key);
        else
            width=.50;
            if strncmp(name,'File',4)
                width=.35;
                uicontrol(panels{g},'style','pushbutton','string','Browse...', ...
                    'units','normalized','position',[.82 y .14 .06], ...
                    'callback',@(src,event) browse_noise(key));
            end
            controls.(key)=uicontrol(panels{g},'style','edit','units','normalized', ...
                'position',[.46 y width .06],'horizontalalignment','left', ...
                'string',last.raw.(key),'callback',@edited,'tag',key);
        end
    end
end
hint=uicontrol(fig,'style','text','units','normalized','position',[.26 .205 .72 .075], ...
    'horizontalalignment','left','string', ...
    {'Fields use Hz, seconds, A/cycle, Hz/volt, farads and ohms as labelled.'; ...
     'Lists/ranges: [1000 2000 4000] or 1000:1000:4000. No executable expressions.'});
uicontrol(fig,'style','text','units','normalized','position',[.02 .16 .22 .045], ...
    'horizontalalignment','left','string','Generated script filename');
script_control=uicontrol(fig,'style','edit','units','normalized', ...
    'position',[.26 .16 .72 .05],'string',last.script_name, ...
    'horizontalalignment','left','callback',@edited,'tag','pll_script_name');
run_control=uicontrol(fig,'style','checkbox','units','normalized', ...
    'position',[.26 .10 .28 .05],'string','Run the script','value',last.run_script, ...
    'callback',@edited,'tag','pll_run_script');
viewer_control=uicontrol(fig,'style','checkbox','units','normalized', ...
    'position',[.55 .10 .43 .05],'string','Enable data viewer after run', ...
    'value',strcmp(last.raw.o_bEnableDataViewer,'1'),'callback',@edited, ...
    'tag','o_bEnableDataViewer');
controls.o_bEnableDataViewer=viewer_control;
uicontrol(fig,'style','pushbutton','units','normalized','position',[.02 .035 .22 .055], ...
    'string','Reset everything','callback',@reset_all,'tag','pll_reset');
uicontrol(fig,'style','pushbutton','units','normalized','position',[.26 .035 .35 .055], ...
    'string','Generate script...','callback',@generate,'tag','pll_generate');
uicontrol(fig,'style','pushbutton','units','normalized','position',[.65 .035 .33 .055], ...
    'string','Exit (retain inputs)','callback',@close_gui);
refresh();
if wait_for_close
    waitfor(fig);
    if ~isempty(pending_script)
        try
            evalin('base',['run(''' strrep(pending_script,'''','''''') ''');']);
        catch err
            warning('Generated PLL run failed: %s',err.message);
            errordlg(err.message,'PLL run failed (script was saved)');
        end
    end
end

    function edited(src,event)
        capture();
        try
            persist();
        catch err
            errordlg(err.message,'Could not save last PLL setup');
        end
        refresh();
    end

    function capture()
        names=fieldnames(controls);
        for j=1:numel(names)
            key=names{j};
            h=controls.(key);
            style=get(h,'style');
            if strcmp(style,'checkbox')
                last.raw.(key)=num2str(get(h,'value'));
            elseif strcmp(style,'popupmenu')
                choices=get(h,'string');
                last.raw.(key)=choices{get(h,'value')};
            else
                last.raw.(key)=get(h,'string');
            end
        end
        last.section=get(section_control,'value');
        last.run_script=get(run_control,'value');
        last.script_name=get(script_control,'string');
    end

    function persist()
        temporary=[tempname(state_directory) '.mat'];
        cleanup=onCleanup(@() remove_temporary(temporary));
        save(temporary,'last','-v7');
        [ok,message]=movefile(temporary,state_file,'f');
        if ~ok
            error('Cannot save local configurator state: %s',message);
        end
    end

    function change_section(src,event)
        edited(src,event);
    end

    function refresh()
        for j=1:numel(panels)
            set(panels{j},'visible','off');
        end
        set(panels{last.section},'visible','on');
        file_vco=get(controls.p_bUseVCOFromFile,'value');
        file_ref=get(controls.p_bUseTCXOFromFile,'value');
        full=get(controls.p_filter_override,'value');
        third=get(controls.p_filter_override_3rdpole_only,'value');
        enable({'p_Kvco_Hz_volt','p_Nvco_ref_dBc','p_Fvco_ref_offset_Hz'},~file_vco);
        enable({'p_Ntcxo_ref_dBc','p_Ftcxo_ref_offset_Hz'},~file_ref);
        enable({'p_FileVCO'},file_vco);
        enable({'p_FileTCXO'},file_ref);
        enable({'p_CC1','p_CC2','p_RR2'},full);
        enable({'p_CC3','p_RR3'},full || third);
        sweep=get(controls.o_bRunSweep,'value');
        enable({'o_sweep_parameter','o_sweep_type','o_sweep_values','o_sweep_start', ...
            'o_sweep_stop','o_sweep_step','o_sweep_points_per_octave','o_bSuppressSweepPlots'},sweep);
        sweep_type=get(controls.o_sweep_type,'value');
        keys={'o_sweep_values','o_sweep_start','o_sweep_stop','o_sweep_step','o_sweep_points_per_octave'};
        visible=[sweep_type==1 sweep_type~=1 sweep_type~=1 sweep_type==2 sweep_type==3];
        for j=1:numel(keys)
            state='off';
            if visible(j)
                state='on';
            end
            set(controls.(keys{j}),'visible',state);
            set(labels.(keys{j}),'visible',state);
        end
        if last.section==2
            set(hint,'string',{'File mode replaces reference NOISE only; F_tcxo_Hz is still used.'; ...
                'The core extends noise endpoints outside the measured offset range.'});
        elseif last.section==3
            set(hint,'string',{'File mode replaces VCO noise and Kvco; requested output frequency is still used.'; ...
                'Disabled manual entries are retained for later editing.'});
        elseif last.section==4
            set(hint,'string',{'Synthesize at each point, then apply the same selected component overrides.'; ...
                'Choose full override OR third-pole-only override.'});
        elseif last.section==7
            guidance='List accepts literals/ranges; start/stop/step uses start:step:stop.';
            if sweep_type==3
                guidance='Log: positive start/stop, integer points/octave; exact stop included.';
            end
            set(hint,'string',{guidance; ...
                'bSuppressSweepPlots skips core figures/exports for sweeps; browse with the viewer.'; ...
                'Results are checkpointed after each point; failed points retain their error.'});
        else
            set(hint,'string',{'Numeric entries accept literals, lists and start:step:stop; no code evaluation.'; ...
                'RMS phase error is double-sided; residual FM retains the existing unverified-method warning.'});
        end
    end

    function enable(keys,yes)
        state='off';
        if yes
            state='on';
        end
        for j=1:numel(keys)
            set(controls.(keys{j}),'enable',state);
        end
    end

    function browse_noise(key)
        [name,directory]=uigetfile('*.mat','Choose pn_struct noise file',tool_directory);
        if isequal(name,0)
            return;
        end
        set(controls.(key),'string',fullfile(directory,name));
        edited([],[]);
    end

    function reset_all(src,event)
        answer=questdlg('Reset all fields and run controls to the human-created runner defaults?', ...
            'Reset PLL setup','Reset','Cancel','Cancel');
        if ~strcmp(answer,'Reset')
            return;
        end
        names=fieldnames(controls);
        for j=1:numel(names)
            key=names{j};
            h=controls.(key);
            if strcmp(get(h,'style'),'checkbox')
                set(h,'value',strcmp(raw_defaults.(key),'1'));
            elseif strcmp(get(h,'style'),'popupmenu')
                choices=get(h,'string');
                set(h,'value',find(strcmp(choices,raw_defaults.(key)),1));
            else
                set(h,'string',raw_defaults.(key));
            end
        end
        set(section_control,'value',1);
        set(run_control,'value',0);
        set(script_control,'string','aa_run_user_config_XXXX_design.m');
        edited([],[]);
    end

    function generate(src,event)
        capture();
        try
            persist();
            config=defaults;
            for scope={'p','o'}
                prefix=scope{1};
                field='pll_inputs_s';
                if strcmp(prefix,'o')
                    field='run_options_s';
                end
                names=fieldnames(config.(field));
                for j=1:numel(names)
                    key=[prefix '_' names{j}];
                    text=last.raw.(key);
                    if strcmp(prefix,'o') && strcmp(names{j},'sweep_values') && ...
                            (~strcmp(last.raw.o_sweep_type,'List') || strcmp(last.raw.o_bRunSweep,'1'))
                        value=rfdude_pll_sweep_values(last.raw.o_sweep_type,text, ...
                            last.raw.o_sweep_start,last.raw.o_sweep_stop, ...
                            last.raw.o_sweep_step,last.raw.o_sweep_points_per_octave);
                    elseif ischar(config.(field).(names{j}))
                        value=text;
                    else
                        try
                            value=rfdude_pll_parse_value(text);
                        catch err
                            error('%s: %s',names{j},err.message);
                        end
                    end
                    config.(field).(names{j})=value;
                end
            end
            [name,directory]=uiputfile('*.m','Generate PLL run script', ...
                fullfile(tool_directory,last.script_name));
            if isequal(name,0)
                return;
            end
            filename=fullfile(directory,name);
            overwrite=false;
            if exist(filename,'file')
                answer=questdlg('Replace this existing run script?', ...
                    'Confirm overwrite','Replace','Cancel','Cancel');
                if ~strcmp(answer,'Replace')
                    return;
                end
                overwrite=true;
            end
            rfdude_pll_generate_script(config,filename,overwrite);
            last.script_name=name;
            set(script_control,'string',name);
            persist();
        catch err
            errordlg(err.message,'PLL setup could not be generated');
            return;
        end
        if last.run_script
            delete(fig);
            if wait_for_close
                pending_script=filename;
                return;
            end
            try
                execute_generated_script(filename);
            catch err
                warning('Generated PLL run failed: %s',err.message);
                errordlg(err.message,'PLL run failed (script was saved)');
            end
        else
            msgbox(sprintf('Saved:\n%s\nRun it by name from its directory in Octave.\nYou may keep editing or exit.',filename), ...
                'PLL script generated');
        end
    end

    function close_gui(src,event)
        capture();
        try
            persist();
        catch err
            errordlg(err.message,'Could not save last PLL setup; window retained');
            return;
        end
        delete(fig);
    end
end

function raw=raw_configuration(config)
raw=struct();
for scope={'p','o'}
    prefix=scope{1};
    field='pll_inputs_s';
    if strcmp(prefix,'o')
        field='run_options_s';
    end
    for name=fieldnames(config.(field)).'
        value=config.(field).(name{1});
        if ~ischar(value)
            value=mat2str(double(value),17);
        end
        raw.([prefix '_' name{1}])=value;
    end
end
end

function key=field_key(group,name)
prefix='p_';
if group==7
    prefix='o_';
end
key=[prefix name];
end

function yes=is_boolean(name)
yes=strncmp(name,'b',1) || strncmp(name,'filter_override',15);
end

function label=field_label(name)
switch name
    case 'CC1', label='C1 override (F)';
    case 'CC2', label='C2 override (F)';
    case 'CC3', label='C3 override (F)';
    case 'RR2', label='R2 override (ohm)';
    case 'RR3', label='R3 override (ohm)';
    case 'mult', label='Output multiplier/divider ratio';
    case 'def_filename', label='Results basename (.mat)';
    case 'sweep_start', label='sweep start (parameter units)';
    case 'sweep_stop', label='sweep stop (parameter units)';
    case 'sweep_step', label='sweep step (parameter units)';
    case 'sweep_points_per_octave', label='points per octave';
    otherwise, label=strrep(name,'_',' ');
end
end

function execute_generated_script(filename)
run(filename);
end

function remove_temporary(filename)
if exist(filename,'file')==2
    delete(filename);
end
end
